async selectBundle(name, enabled) {
	// DSHA_AUTO_REVIEW_NATIVE_DISABLED_V1 / DSHA_AUTO_REVIEW_ALIAS_V2 / DSHA_SIGNED_WEB_INTENT_V1:
	// The signed historical wrapper inserts the same official auto-review
	// row. One visible official control must own both selection aliases.
	const autoAliases = ["dsh-auto-review", "@deepseek-ai/dsh-experimental-auto-review"];
	const signedWrappers = ["dsh-device-shell-guide", "dsh-task-notifier", "dsh-status-overlay", "dsh-web-mobile", "dsh-computer-use-android", "dsh-tool-vscreen", "dsh-app-integration"];
	const managedAliases = autoAliases.includes(name) ? autoAliases : signedWrappers.includes(name) ? [name] : undefined;
	if (managedAliases !== undefined) {
		const canonicalName = autoAliases.includes(name) ? autoAliases[1] : name;
		const webMarker = autoAliases.includes(name) ? "DSHA_WEB_AUTO_REVIEW_DISABLED_V1\n" : "DSHA_WEB_BUILTIN_DISABLED_V1\n";
		const markers = managedAliases.map(alias => join(this.profile.dir, "node_modules", alias + ".disabled"));
		const markerStates = await Promise.all(markers.map(async marker => {
			try { return await readFile(marker, "utf8"); }
			catch (error) { if (error.code === "ENOENT") return undefined; throw error; }
		}));
		if (enabled && markerStates.some(state => state !== undefined && state !== webMarker))
